# ============================================================================
# دوال مساعدة مطابقة لمنطق وحدات اللعبة (Controllers)
# ============================================================================

def _to_int(value: Any, default: int = 0) -> int:
    try:
        return int(float(value))
    except (TypeError, ValueError):
        return default


def _get_building_level(live_memory: Dict[str, Any], target_bid: int) -> Tuple[int, int]:
    """يرجع (lv, starLv) لأعلى مبنى مطابق لـ target_bid في cityCtrl.blist."""
    city = live_memory.get("cityCtrl") or {}
    blist = city.get("blist") or []
    best_lv = 0
    best_star = 0
    for entry in blist:
        binfo = entry.get("binfo", entry) if isinstance(entry, dict) else {}
        if _to_int(binfo.get("bid")) == target_bid:
            lv = _to_int(binfo.get("lv"))
            star = _to_int(binfo.get("starLv"))
            if (lv, star) > (best_lv, best_star):
                best_lv, best_star = lv, star
    return best_lv, best_star


def _calc_drill_grounds_base(live_memory: Dict[str, Any]) -> int:
    """buildLogic.getBuildBaseValue(BUILDID.DRILL_GROUDS, 'capacity', bcell)."""
    lv, star_lv = _get_building_level(live_memory, BUILD_ID_DRILL_GROUNDS)
    if lv <= 0:
        return 0
    base = DRILL_GROUND_CAPACITY.get(lv, 0)
    if star_lv > 0:
        base += DRILL_GROUND_STAR_CAPACITY.get(star_lv, 0)
    return base


def _calc_technology_bonus(live_memory: Dict[str, Any]) -> Tuple[int, float]:
    """
    يرجع (tech_add, tech_group_pct) مطابقاً لـ technologyCtrl:getTechnologyPower:
      - tech_add: SINGLE_TROOP_STRENGTH (43)
      - tech_group_pct: CONQUEST_WAR (73) + PYRAMID (77) + LEGEND (95)
    """
    tech_ctrl = live_memory.get("technologyCtrl") or {}
    tech_add = 0
    tech_group_pct = 0.0
    for _, item in tech_ctrl.items():
        if not isinstance(item, (list, tuple)) or len(item) < 2:
            continue
        tid_base = _to_int(item[0])
        lv = _to_int(item[1])
        if tid_base <= 0 or lv <= 0:
            continue
        full_id = tid_base * 100 + lv
        if full_id in TECH_MARCH_FLAT:
            tech_add += TECH_MARCH_FLAT[full_id]
        if full_id in TECH_MARCH_PCT:
            tech_group_pct += TECH_MARCH_PCT[full_id]
    return int(tech_add), tech_group_pct


def _calc_server_buffs(
    live_memory: Dict[str, Any],
    now: Optional[int] = None,
    is_mass: bool = False,
) -> Tuple[int, int]:
    """
    يقرأ التعزيزات النشطة في buffCtrl (بما فيها VIP المفعّل وتعزيزات التوسعة المؤقتة).
    يرجع (flat_add, pct_per_1000).
    """
    buffs = live_memory.get("buffCtrl") or []
    if isinstance(buffs, dict):
        buffs = list(buffs.values())

    flat_add = 0
    pct_per_1000 = 0
    for b in buffs:
        if not isinstance(b, dict):
            continue
        bid = _to_int(b.get("id"))
        if bid not in BUFF_MARCH:
            continue
        duration = _to_int(b.get("time"))
        begin_time = _to_int(b.get("beginTime"))
        # إذا مُرِّر now نتحقق من عدم انتهاء صلاحية التعزيز المؤقت
        if now is not None and duration > 0 and (begin_time + duration) <= now:
            continue
        effect_type, val = BUFF_MARCH[bid]
        if effect_type == BUFF_EFFECT_MARCH_VALUE_LIMIT_BOOST:
            flat_add += val
        elif effect_type == BUFF_EFFECT_MARCH_LIMIT_BOOST:
            pct_per_1000 += val
        elif is_mass and effect_type == BUFF_EFFECT_MASS_MARCH_VALUE_LIMIT_BOOST:
            flat_add += val
        elif is_mass and effect_type == BUFF_EFFECT_MASS_MARCH_LIMIT_BOOST:
            pct_per_1000 += val
    return flat_add, pct_per_1000


def _calc_achievement_pct_per_1000(live_memory: Dict[str, Any]) -> int:
    """achievementctrl:getBuffValue(gBuffEffect.MARCH_LIMIT_BOOST)."""
    ach_ctrl = live_memory.get("achievementctrl") or {}
    ach_list = ach_ctrl.get("list") or {}
    total = 0
    for v in ach_list.values():
        if not isinstance(v, dict):
            continue
        max_done_id = _to_int(v.get("maxDoneID"))
        if max_done_id in ACHIEVEMENT_MARCH_PCT_PER_1000:
            total += ACHIEVEMENT_MARCH_PCT_PER_1000[max_done_id]
    return total


def _calc_pet_flat(live_memory: Dict[str, Any]) -> int:
    """petCtrl:getPetAttributeAdd(gBuffEffect.MARCH_VALUE_LIMIT_BOOST)."""
    pet_ctrl = live_memory.get("petCtrl") or {}
    pet_list = pet_ctrl.get("petList") or {}
    total = 0
    for pet in pet_list.values():
        if not isinstance(pet, dict):
            continue
        pid = _to_int(pet.get("petid"))
        lv = _to_int(pet.get("level"))
        total += PET_LEVEL_MARCH_FLAT.get((pid, lv), 0)
    return total


def _calc_kingdom_level_flat(live_memory: Dict[str, Any]) -> int:
    """kingdomLevelDataModuleAPI:getBuff(gBuffEffect.MARCH_VALUE_LIMIT_BOOST)."""
    kl_ctrl = live_memory.get("playerKingdomLevelCtrl") or {}
    if not kl_ctrl.get("isUnlock"):
        return 0
    castle_lv, _ = _get_building_level(live_memory, BUILD_ID_CASTLE)
    # kingdomLevelltCtrl:getBuffValidCastleLvMin() == 6
    if castle_lv < 6:
        return 0
    kingdom_lv = _to_int(kl_ctrl.get("level"))
    return KINGDOM_LV_MARCH_FLAT.get(kingdom_lv, 0)


def _calc_nebula_tower_flat(live_memory: Dict[str, Any]) -> int:
    """nebulaActivityCtrl:getNebulaTowerBuffEffect(gBuffEffect.MARCH_VALUE_LIMIT_BOOST)."""
    nt_ctrl = live_memory.get("nebulaTowerCtrl") or {}
    if not nt_ctrl or nt_ctrl.get("isLock", True):
        return 0
    tower_lv = _to_int(nt_ctrl.get("level"))
    return NEBULA_TOWER_MARCH_FLAT.get(tower_lv, 0)


def _calc_hero_biography_flat(live_memory: Dict[str, Any]) -> int:
    """heroBiographyCtrl:queryHeroBiographyBuff(gBuffEffect.MARCH_VALUE_LIMIT_BOOST)."""
    bio_ctrl = live_memory.get("heroBiographyCtrl") or {}
    active_skills = bio_ctrl.get("activeSkillList") or {}
    total = 0
    for sid_str in active_skills:
        sid = _to_int(sid_str)
        if sid in HERO_BIO_MARCH_FLAT:
            total += HERO_BIO_MARCH_FLAT[sid]
    return int(total)


def _calc_hero_dress_flat(live_memory: Dict[str, Any]) -> int:
    """heroCtrl:getTheActiveBuff(gBuffEffect.MARCH_VALUE_LIMIT_BOOST) (مظاهر الأبطال المملوكة)."""
    hero_ctrl = live_memory.get("heroSysCtrl") or {}
    hero_list = hero_ctrl.get("heroList") or {}
    total = 0
    for hero in hero_list.values():
        if not isinstance(hero, dict):
            continue
        state = _to_int(hero.get("state"))
        if state in (HERO_STATE_DEAD, HERO_STATE_CAPTURED):
            continue
        dress_list = (hero.get("dress") or {}).get("list") or {}
        for did_str in dress_list:
            did = _to_int(did_str)
            if did in HERO_DRESS_MARCH_FLAT:
                total += HERO_DRESS_MARCH_FLAT[did]
    return total


def _calc_war_gem_flat(live_memory: Dict[str, Any]) -> int:
    """warGemCtrl:getBuffPlus(gBuffEffect.MARCH_VALUE_LIMIT_BOOST) للوحة النشطة."""
    wg_ctrl = live_memory.get("warGemCtrl") or {}
    gem_data = wg_ctrl.get("gemData") or {}
    panels = gem_data.get("panel") or []
    act_panel_id = _to_int(gem_data.get("actPanelId"), 1)
    if not isinstance(panels, list) or act_panel_id < 1 or act_panel_id > len(panels):
        return 0
    active_panel = panels[act_panel_id - 1]
    if not isinstance(active_panel, dict):
        return 0
    total = 0
    for hole_list in active_panel.values():
        if not isinstance(hole_list, list):
            continue
        for gem_id in hole_list:
            gid = _to_int(gem_id)
            if gid > 0 and gid in WAR_GEM_MARCH_FLAT:
                total += WAR_GEM_MARCH_FLAT[gid]
    return total


def _calc_equipment_flat(live_memory: Dict[str, Any], now: Optional[int] = None) -> Tuple[int, int]:
    """
    يرجع (equip_buff_flat, equip_attr_flat) للعتاد المرتدى حالياً (wear == 1):
      - equip_buff_flat: خاصية 78 (أساسية + تقوية slv + إضافية extra)
      - equip_attr_flat: خاصية specialType بمفتاح attrID == 3 (DISPATCH_TROOP_COUNT_NUM)
    """
    eq_ctrl = live_memory.get("equipmentCtrl") or {}
    eq_arr = eq_ctrl.get("equipment_array") or []
    buff_flat = 0
    attr_flat = 0
    for eq in eq_arr:
        if not isinstance(eq, dict) or _to_int(eq.get("wear")) != 1:
            continue
        if now is not None:
            exp_t = _to_int(eq.get("endTime") or eq.get("overdueTime") or eq.get("stopTime"))
            if exp_t > 0 and exp_t <= now:
                continue
        eid = _to_int(eq.get("eid"))
        qly = _to_int(eq.get("qly"))
        slv = _to_int(eq.get("slv"))

        # الخصائص الأساسية + التقوية + الخاصة من equipment_base_property_config
        cfg = EQUIP_MARCH_FLAT.get((eid, qly))
        if cfg:
            base_val, add_triples, special_val = cfg
            val = base_val
            for j in range(0, len(add_triples) - 2, 3):
                min_lv, max_lv, step = add_triples[j], add_triples[j + 1], add_triples[j + 2]
                if slv >= min_lv:
                    effective_lv = min(slv, max_lv)
                    val += step * (effective_lv - min_lv + 1)
            buff_flat += val
            attr_flat += special_val

        # الخصائص الإضافية (extra)
        for ex in eq.get("extra") or []:
            if isinstance(ex, (list, tuple)) and len(ex) >= 2:
                if _to_int(ex[0]) == EQUIP_PROP_MARCH_VALUE_LIMIT_BOOST:
                    buff_flat += _to_int(ex[1])
    return buff_flat, attr_flat


def _calc_castle_dress_attr(live_memory: Dict[str, Any], now: Optional[int] = None) -> int:
    """dressMgr -> attributeSystem.query(DISPATCH_TROOP_COUNT_NUM) من المظاهر المملوكة والمستخدمة."""
    dress_ctrl = live_memory.get("dressCtrl") or {}
    dress_list = dress_ctrl.get("list") or {}
    total = 0
    expired_ids: set = set()
    # مظاهر مملوكة (ownAttribute) مع فحص انتهاء الصلاحية عند تمرير now
    for did_str, d_info in (dress_list.items() if isinstance(dress_list, dict) else []):
        did = _to_int(did_str)
        if now is not None and isinstance(d_info, dict):
            stop_t = _to_int(d_info.get("stopTime") or d_info.get("endTime"))
            if stop_t > 0 and stop_t <= now:
                expired_ids.add(did)
                continue
        if did in DRESS_OWN_MARCH_FLAT:
            total += DRESS_OWN_MARCH_FLAT[did]
    # مظاهر مفعّلة حالياً (useAttribute)
    setting = dress_ctrl.get("setting") or {}
    if isinstance(setting, dict):
        for did_val in setting.values():
            did = _to_int(did_val)
            if did not in expired_ids and did in DRESS_USE_MARCH_FLAT:
                total += DRESS_USE_MARCH_FLAT[did]
    return total


