HERO_STATE_NORMAL = 1
HERO_STATE_DEAD = 2
HERO_STATE_CAPTURED = 3
HERO_SKILL_ACTIVE_BATTLE = 2

def _get_hero_list_map(live_memory: Dict[str, Any]) -> Dict[int, Dict[str, Any]]:
    """استخراج خريطة الأبطال المملوكين {hero_id: hero_info} من heroSysCtrl.heroList."""
    hero_sys = live_memory.get("heroSysCtrl") or {}
    raw = hero_sys.get("heroList") if isinstance(hero_sys, dict) else None
    if not raw:
        hero_ctrl = live_memory.get("heroCtrl") or {}
        if isinstance(hero_ctrl, dict):
            raw = hero_ctrl.get("heroList") or hero_ctrl.get("heroListInfo") or hero_ctrl
        elif isinstance(hero_ctrl, list):
            raw = hero_ctrl

    out: Dict[int, Dict[str, Any]] = {}
    if isinstance(raw, dict):
        for k, v in raw.items():
            if isinstance(v, dict):
                hid = _to_int(v.get("heroID") or v.get("id") or k)
                if hid > 0:
                    out[hid] = v
    elif isinstance(raw, list):
        for v in raw:
            if isinstance(v, dict):
                hid = _to_int(v.get("heroID") or v.get("id") or v.get("cId"))
                if hid > 0:
                    out[hid] = v
    return out


def _get_hero_palace_buff(hero_id: int, owned_hero_ids: set) -> Tuple[int, int, int, int]:
    """مطابق لدالة heroCtrl:getHeroPalaceBuff(heroID) -> (skillAdd, awakeAdd, stuntAdd, masteryAdd)."""
    palace_type = None
    for pt, hids in HERO_PALACE_HEROTYPE.items():
        if hero_id in hids:
            palace_type = pt
            break
    if palace_type is None:
        return (0, 0, 0, 0)

    own_count = sum(1 for h in HERO_PALACE_HEROTYPE[palace_type] if h in owned_hero_ids)
    best = (0, 0, 0, 0)
    for req_heroes, sk_add, aw_add, st_add, ma_add in HERO_PALACE_ADDITION.get(palace_type, []):
        if own_count >= req_heroes:
            best = (sk_add, aw_add, st_add, ma_add)
    return best


def _get_inherit_attr_by_level(level: int) -> Optional[Tuple[int, int, int, int, int, int]]:
    for row in HERO_INHERIT_ATTR:
        if row[0] <= level <= row[1]:
            return row
    return None


def calculate_heroes_march_add(
    live_memory: Dict[str, Any],
    hero_ids: Sequence[Union[int, str]],
    lieutenant_map: Optional[Dict[Union[int, str], Union[int, str]]] = None,
    only_normal_state: bool = False,
) -> Dict[str, Any]:
    """
    حساب زيادة سعة المسيرة للأبطال المُمررين (والأبطال المساعدين اختيارياً)
    مطابق 100% لـ WorldDispatchArmyViewPanel:updateHeroEx() و heroltCtrl:getHerosMarchCapacity().
    ملاحظة: بوف مظاهر الأبطال السلبية (getBuff) محسوب مسبقاً ضمن السعة الأساسية بدون أبطال
    ولا يُعاد جمعه هنا لمنع التكرار (مثل طرح hero_dressAdd في اللعبة).
    """
    heroes_map = _get_hero_list_map(live_memory)
    owned_ids = set(heroes_map.keys())
    per_hero: List[Dict[str, Any]] = []
    total_hero_add = 0

    seen: set = set()
    for raw_hid in hero_ids:
        hid = _to_int(raw_hid)
        if hid <= 0 or hid in seen:
            continue
        seen.add(hid)

        hinfo = heroes_map.get(hid)
        if not hinfo:
            per_hero.append({
                "hero_id": hid,
                "found": False,
                "level": 0,
                "quality": 0,
                "state": 0,
                "level_march_add": 0,
                "skill_march_add": 0,
                "total": 0,
            })
            continue

        state = _to_int(hinfo.get("state", HERO_STATE_NORMAL))
        level = _to_int(hinfo.get("level", 1))
        quality = _to_int(hinfo.get("quality", 1))
        rarity = HERO_RARITY.get(hid, 0)

        if state in (HERO_STATE_DEAD, HERO_STATE_CAPTURED) or (only_normal_state and state != HERO_STATE_NORMAL):
            per_hero.append({
                "hero_id": hid,
                "found": True,
                "level": level,
                "quality": quality,
                "rarity": rarity,
                "state": state,
                "skipped_state": True,
                "level_march_add": 0,
                "skill_march_add": 0,
                "total": 0,
            })
            continue

        level_add = HERO_LEVEL_MARCH_ADD.get(rarity, {}).get(level, 0)
        skill_add_palace, _awake_add_palace, _stunt_add_palace, mastery_add_palace = _get_hero_palace_buff(hid, owned_ids)

        skill_val = 0.0
        skill_list = hinfo.get("skillList") or {}
        sk_iter = skill_list.values() if isinstance(skill_list, dict) else (skill_list if isinstance(skill_list, list) else [])
        for sinfo in sk_iter:
            if not isinstance(sinfo, dict) or not sinfo.get("isActive"):
                continue
            stype = _to_int(sinfo.get("skillType"))
            real_sid = stype * 100 + quality
            cfg = HERO_SKILL_MARCH_96.get(real_sid)
            if cfg and cfg[0] == HERO_SKILL_ACTIVE_BATTLE:
                skill_val += cfg[1] * (1.0 + skill_add_palace / 1000.0)

        adv = hinfo.get("advancedSkill")
        if isinstance(adv, dict) and adv.get("skillID"):
            adv_sid = _to_int(adv.get("skillID"))
            for at, _bm, bv in HERO_MASTERY_SKILL_MARCH_96.get(adv_sid, []):
                if at == HERO_SKILL_ACTIVE_BATTLE:
                    skill_val += bv * (1.0 + mastery_add_palace / 1000.0)

        skill_int = math.floor(skill_val)
        hero_sum = level_add + skill_int
        total_hero_add += hero_sum
        per_hero.append({
            "hero_id": hid,
            "found": True,
            "level": level,
            "quality": quality,
            "rarity": rarity,
            "state": state,
            "level_march_add": level_add,
            "skill_march_add": skill_int,
            "total": hero_sum,
        })

    lieutenant_add = 0
    if lieutenant_map:
        for main_raw, lie_raw in lieutenant_map.items():
            main_id = _to_int(main_raw)
            lie_id = _to_int(lie_raw)
            hinfo = heroes_map.get(lie_id)
            if not hinfo:
                continue
            state = _to_int(hinfo.get("state", HERO_STATE_NORMAL))
            if state in (HERO_STATE_DEAD, HERO_STATE_CAPTURED):
                continue
            level = _to_int(hinfo.get("level", 1))
            inher = _get_inherit_attr_by_level(level)
            main_rarity = HERO_RARITY.get(main_id, 0)
            special_awake_add = inher[5] if (inher and main_rarity >= 4) else 0
            _sk, _aw, _st, mastery_add_palace = _get_hero_palace_buff(lie_id, owned_ids)
            adv = hinfo.get("advancedSkill")
            if isinstance(adv, dict) and adv.get("skillID"):
                adv_sid = _to_int(adv.get("skillID"))
                for _at, bm, bv in HERO_MASTERY_SKILL_MARCH_96.get(adv_sid, []):
                    val = float(bv)
                    if inher and inher[3]:
                        val = val * ((inher[3] + special_awake_add) / 10000.0)
                    if bm == 2:
                        lieutenant_add += math.floor(val * (1.0 + mastery_add_palace / 1000.0))
                    else:
                        lieutenant_add += int(val * (1.0 + mastery_add_palace / 1000.0))

    return {
        "hero_total": total_hero_add + lieutenant_add,
        "main_heroes_add": total_hero_add,
        "lieutenants_add": lieutenant_add,
        "heroes": per_hero,
    }


def calculate_march_capacity(
    live_memory: Dict[str, Any],
    *,
    hero_ids: Optional[Sequence[Union[int, str]]] = None,
    lieutenant_map: Optional[Dict[Union[int, str], Union[int, str]]] = None,
    only_normal_state: bool = False,
    now: Optional[int] = None,
    is_mass: bool = False,
    is_arena: bool = False,
) -> Dict[str, Any]:
    """
    تحسب سعة المسيرة بدون أبطال وفق منطق buildLogic.getExpArmyCount() الأصلي.

    المعاملات:
        live_memory: قاموس الذاكرة الحية للقلعة (من JSON السيرفر).
        now: الطابع الزمني الحالي (Unix timestamp) للتحقق من انتهاء التعزيزات المؤقتة.
             اتركه None عند فحص لقطة محفوظة (snapshot) دون فلترة زمنية.
        is_mass: True في حال كانت المسيرة حشداً (moveLineTypeMass).
        is_arena: True لحساب سعة الساحة (يستثني برج السديم كما في getArenaExpArmyCount).

    المخرجات:
        قاموس يحتوي على:
          - total: إجمالي سعة المسيرة بدون أبطال (int)
          - base: سعة ساحة التدريب الأساسية
          - add: إجمالي الإضافات (ثابتة + نسبة مئوية)
          - breakdown: تفصيل كامل لكل مصدر
    """
    base = _calc_drill_grounds_base(live_memory)
    default = DEFAULT_EXP_ARMY_COUNT
    tech_add, tech_group_pct = _calc_technology_bonus(live_memory)

    server_flat, server_pct_1000 = _calc_server_buffs(live_memory, now=now, is_mass=is_mass)
    ach_pct_1000 = _calc_achievement_pct_per_1000(live_memory)

    pet_flat = _calc_pet_flat(live_memory)
    kingdom_lv_flat = _calc_kingdom_level_flat(live_memory)
    nebula_tower_flat = 0 if is_arena else _calc_nebula_tower_flat(live_memory)
    hero_bio_flat = _calc_hero_biography_flat(live_memory)
    war_gem_flat = _calc_war_gem_flat(live_memory)
    equip_buff_flat, equip_attr_flat = _calc_equipment_flat(live_memory, now=now)

    buff_value_add = (
        server_flat
        + pet_flat
        + kingdom_lv_flat
        + nebula_tower_flat
        + hero_bio_flat
        + war_gem_flat
        + equip_buff_flat
    )

    dress_attr = _calc_castle_dress_attr(live_memory, now=now)
    attr_add = equip_attr_flat + dress_attr
    hero_dress_add = _calc_hero_dress_flat(live_memory)

    flat_add = default + tech_add + buff_value_add + attr_add + hero_dress_add
    buff_percent_add = (server_pct_1000 + ach_pct_1000) / 1000.0
    effective_pct = buff_percent_add + (0.0 if is_arena else tech_group_pct)

    # المعادلة الأصلية: math.floor((base + total_add) * (buff_percent_add + techGroupAdd))
    buff_add = math.floor((base + flat_add) * effective_pct)
    total_add = flat_add + buff_add
    total = base + total_add

    base_without_heroes = total
    hero_details = None
    hero_total = 0
    if hero_ids:
        hero_details = calculate_heroes_march_add(
            live_memory,
            hero_ids=hero_ids,
            lieutenant_map=lieutenant_map,
            only_normal_state=only_normal_state,
        )
        hero_total = hero_details["hero_total"]
        total = base_without_heroes + hero_total

    return {
        "total": total,
        "base_without_heroes": base_without_heroes,
        "hero_total": hero_total,
        "hero_details": hero_details,
        "base": base,
        "add": total_add,
        "breakdown": {
            "drill_grounds_base": base,
            "default": default,
            "technology_flat": tech_add,
            "technology_group_pct": tech_group_pct,
            "buff_value_add": {
                "server_buffs": server_flat,
                "pet": pet_flat,
                "kingdom_level": kingdom_lv_flat,
                "nebula_tower": nebula_tower_flat,
                "hero_biography": hero_bio_flat,
                "war_gem": war_gem_flat,
                "equipment": equip_buff_flat,
                "subtotal": buff_value_add,
            },
            "attr_add": {
                "equipment_special": equip_attr_flat,
                "castle_dress": dress_attr,
                "subtotal": attr_add,
            },
            "hero_dress_add": hero_dress_add,
            "buff_percent_add": buff_percent_add,
            "percent_bonus_soldiers": buff_add,
        },
    }


def get_march_capacity_no_heroes(
    live_memory: Dict[str, Any],
    *,
    now: Optional[int] = None,
    is_mass: bool = False,
) -> int:
    """دالة مختصرة للبوت ترجع رقم سعة المسيرة بدون أبطال مباشرة (int)."""
    return calculate_march_capacity(live_memory, now=now, is_mass=is_mass)["total"]


def get_march_capacity(
    live_memory: Dict[str, Any],
    hero_ids: Optional[Sequence[Union[int, str]]] = None,
    *,
    lieutenant_map: Optional[Dict[Union[int, str], Union[int, str]]] = None,
    only_normal_state: bool = False,
    now: Optional[int] = None,
    is_mass: bool = False,
    is_arena: bool = False,
) -> int:
    """
    دالة موحدة للبوت:
      - إذا مُررت hero_ids ترجع السعة الكلية مع الأبطال (int).
      - إذا لم تُمرر أبطال ترجع السعة الأساسية بدون أبطال (int).
    """
    return calculate_march_capacity(
        live_memory,
        hero_ids=hero_ids,
        lieutenant_map=lieutenant_map,
        only_normal_state=only_normal_state,
        now=now,
        is_mass=is_mass,
        is_arena=is_arena,
    )["total"]


# المتحكمات الضرورية لحساب سعة المسيرة (تُضاف تلقائياً للقائمة البيضاء في live_memory)
_REQUIRED_MARCH_CONTROLLERS = frozenset({
    "playerKingdomLevelCtrl",
    "nebulaTowerCtrl",
    "heroBiographyCtrl",
})


def _ensure_march_controllers_whitelisted() -> None:
    """
    يضمن عدم تصفية متحكمات مستوى المملكة وبرج السديم وسيرة الأبطال
    بواسطة core.live_memory.ALLOWED_CONTROLLERS أثناء الاتصال.
    """
    try:
        import core.live_memory as lm
        missing = _REQUIRED_MARCH_CONTROLLERS - lm.ALLOWED_CONTROLLERS
        if missing:
            lm.ALLOWED_CONTROLLERS = lm.ALLOWED_CONTROLLERS | missing
    except Exception:
        pass


def _print_result(result: Dict[str, Any], label: str = "", as_json: bool = False) -> None:
    if as_json:
        print(json.dumps(result, ensure_ascii=False, indent=2))
        return

    b = result["breakdown"]
    bv = b["buff_value_add"]
    at = b["attr_add"]
    has_heroes = bool(result.get("hero_details"))
    base_title = "سعة المسيرة الكلية بالأبطال" if has_heroes else "سعة المسيرة بدون أبطال"
    header = f"{base_title} ({label})" if label else base_title
    print("\n" + "=" * 62)
    print(f"  ⚔️  {header}: {result['total']:,}")
    print("=" * 62)
    print(f"  • ساحة التدريب (base)          : {b['drill_grounds_base']:>10,}")
    print(f"  • القيمة الافتراضية (default)   : {b['default']:>+10,}")
    print(f"  • الأبحاث (tech_add)            : {b['technology_flat']:>+10,}")
    print(f"  • برج السديم (nebula_tower)     : {bv['nebula_tower']:>+10,}")
    print(f"  • مستوى المملكة (kingdom_level) : {bv['kingdom_level']:>+10,}")
    print(f"  • الحيوان الأليف (pet)          : {bv['pet']:>+10,}")
    print(f"  • سيرة الأبطال (hero_biography) : {bv['hero_biography']:>+10,}")
    print(f"  • أحجار الحرب (war_gem)         : {bv['war_gem']:>+10,}")
    print(f"  • العتاد (equipment)            : {bv['equipment'] + at['equipment_special']:>+10,}")
    print(f"  • المظاهر (castle/hero dress)   : {at['castle_dress'] + b['hero_dress_add']:>+10,}")
    print(f"  • تعزيزات السيرفر (buffCtrl)    : {bv['server_buffs']:>+10,}")
    pct_total = (b["buff_percent_add"] + b["technology_group_pct"]) * 100.0
    print(f"  • النسبة المئوية ({pct_total:.1f}%)        : {b['percent_bonus_soldiers']:>+10,}")
    if has_heroes:
        print("-" * 62)
        print(f"  • السعة الأساسية بدون أبطال     : {result['base_without_heroes']:>10,}")
        for h in result["hero_details"]["heroes"]:
            if not h.get("found"):
                print(f"  • بطل #{h['hero_id']} (غير مملوك)         :         +0")
            elif h.get("skipped_state"):
                print(f"  • بطل #{h['hero_id']} (حالة={h['state']} غير متاح) :         +0")
            else:
                sk_note = f" + مهارات {h['skill_march_add']:,}" if h["skill_march_add"] else ""
                print(f"  • بطل #{h['hero_id']} (Lv.{h['level']} Q.{h['quality']}{sk_note}): {h['total']:>+10,}")
        if result["hero_details"]["lieutenants_add"]:
            print(f"  • إضافة الأبطال المساعدين       : {result['hero_details']['lieutenants_add']:>+10,}")
        print("-" * 62)
        print(f"  ✅ الإجمالي النهائي بالأبطال    : {result['total']:>10,}")
    else:
        print("-" * 62)
        print(f"  ✅ الإجمالي النهائي بدون أبطال  : {result['total']:>10,}")
    print("=" * 62 + "\n")


async def _run_live_castle(args: argparse.Namespace) -> int:
    _ensure_march_controllers_whitelisted()

    from core.game_client import (
        AccountSession,
        GameConnection,
        SessionCache,
        async_login,
        get_account_device_profile,
        sdk_login,
    )

    email = args.email.strip()
    password = args.password.strip() if args.password else None

    user_id, session_id, matched_email = SessionCache.get_account(email)
    if not user_id or not session_id:
        if not password:
            try:
                import core.database as db
                c_data = db.get_castle_by_id(email)
                if c_data and c_data.get("password"):
                    password = c_data["password"]
            except Exception:
                pass

        if password:
            print(f"[*] توثيق الحساب {email} عبر خادم SDK...")
            prof = get_account_device_profile(email)
            auth_res = sdk_login(email, password, device_id=prof["deviceId"])
            if not auth_res.get("success"):
                print(f"[-] فشلت المصادقة: {auth_res.get('error_msg')} (كود: {auth_res.get('error_code')})")
                return 1
            user_id = auth_res["userId"]
            session_id = auth_res["sessionId"]
            matched_email = email
            SessionCache.set_account(
                email,
                user_id,
                session_id,
                device_id=prof["deviceId"],
                model=prof["model"],
                os_version=prof["osVersion"],
            )
        else:
            print(f"[-] الحساب '{email}' غير موجود في session_cache.json؛ مرّر كلمة المرور عبر -p/--password.")
            return 1

    account = AccountSession(
        email=matched_email or email,
        user_id=str(user_id),
        session_id=str(session_id),
        password=password,
    )

    print(f"[*] الاتصال بخادم تسجيل الدخول للحساب: {account.email}...")
    creds = await async_login(account)
    if not creds:
        if account.is_sealed:
            print(f"[-] الحساب محظور: {account.seal_reason}")
        elif account.is_password_error:
            print(f"[-] خطأ في كلمة المرور: {account.auth_error_msg}")
        else:
            print("[-] فشلت المصادقة مع خادم تسجيل الدخول.")
        return 1

    conn = GameConnection(account, creds)
    try:
        ok = await conn.connect()
        if not ok:
            print("[-] فشل الاتصال ببوابة اللعبة.")
            return 1

        print("[*] انتظار تحميل الذاكرة الحية للقلعة (CMD 1000/1)...")
        deadline = time.monotonic() + 20.0
        ready = False
        while time.monotonic() < deadline:
            if getattr(conn, "is_other_device", False):
                print("[-] تم طرد الجلسة من السيرفر بسبب دخول متزامن من جهاز آخر (kick).")
                return 1
            if getattr(conn, "is_sealed", False):
                print("[-] تم رصد إشعار حظر/إغلاق الحساب من السيرفر (seal).")
                return 1
            if not getattr(conn, "_alive", True):
                print("[-] انقطع الاتصال ببوابة اللعبة قبل اكتمال تحميل الذاكرة الحية.")
                return 1

            is_ready, _missing = conn.memory_engine.is_memory_ready()
            if is_ready:
                ready = True
                break

            # Fallback check: cityCtrl.blist + lordInfoCtrl populated even if another optional controller is empty
            snap_check = conn.init_data if isinstance(getattr(conn, "init_data", None), dict) else {}
            city_ok = isinstance(snap_check.get("cityCtrl"), dict) and bool(snap_check["cityCtrl"].get("blist"))
            lord_ok = isinstance(snap_check.get("lordInfoCtrl"), dict) and bool(snap_check["lordInfoCtrl"].get("base"))
            if city_ok and lord_ok and len(snap_check) >= 5:
                ready = True
                break

            await asyncio.sleep(0.15)

        if not ready:
            snap_dbg = conn.memory_engine.get_snapshot()
            is_ready, missing = conn.memory_engine.is_memory_ready()
            print(f"[-] انتهى وقت انتظار تحميل الذاكرة الحية (20s) دون اكتمال البيانات.")
            print(f"    المتحكمات المستلمة ({len(snap_dbg)}): {sorted(snap_dbg.keys())}")
            print(f"    المتحكمات الناقصة: {missing}")
            return 1

        # مهلة قصيرة لضمان اكتمال تفريغ بقية حزم التهيئة المتتالية
        await asyncio.sleep(0.5)
        live_memory = conn.memory_engine.get_snapshot()
        print(f"[+] تم تحميل الذاكرة الحية بنجاح ({len(live_memory)} متحكم).")
        if args.save_memory:
            with open(args.save_memory, "w", encoding="utf-8") as out_f:
                json.dump(live_memory, out_f, ensure_ascii=False, indent=2)
            print(f"[+] تم حفظ لقطة الذاكرة الحية في: {args.save_memory}")

        lord_name = (
            ((live_memory.get("lordInfoCtrl") or {}).get("base") or {}).get("nickName")
            or account.email
        )
        if args.list_heroes:
            hmap = _get_hero_list_map(live_memory)
            print(f"\n[*] الأبطال المملوكون ({len(hmap)}):")
            for hid in sorted(hmap):
                hi = hmap[hid]
                print(f"  - ID={hid} | Lv={hi.get('level')} | Q={hi.get('quality')} | State={hi.get('state')}")

        hero_ids = [x.strip() for x in args.heroes.split(",") if x.strip()] if args.heroes else None
        result = calculate_march_capacity(
            live_memory,
            hero_ids=hero_ids,
            now=int(time.time()),
            is_mass=args.mass,
            is_arena=args.arena,
        )
        _print_result(result, label=f"{lord_name} | {account.email}", as_json=args.json)
        return 0
    finally:
        await conn.close()


def main() -> None:
    if sys.platform == "win32":
        try:
            sys.stdout.reconfigure(encoding="utf-8", errors="replace")
            sys.stderr.reconfigure(encoding="utf-8", errors="replace")
        except Exception:
            pass
        asyncio.set_event_loop_policy(asyncio.WindowsSelectorEventLoopPolicy())

    parser = argparse.ArgumentParser(
        description="حساب سعة المسيرة بدون أبطال بالاتصال المباشر بالقلعة أو من ملف JSON للذاكرة الحية."
    )
    parser.add_argument("--email", type=str, default="", help="إيميل الحساب للاتصال الفعلي بالقلعة")
    parser.add_argument("--password", "-p", type=str, default="", help="كلمة المرور (اختياري عند عدم وجود جلسة مخزنة)")
    parser.add_argument("--file", "-f", type=str, default="", help="مسار ملف JSON محلي للذاكرة الحية (للاختبار بدون اتصال)")
    parser.add_argument("--heroes", type=str, default="", help="معرفات الأبطال مفصولة بفاصلة مثل: 1716,1720 (اختياري؛ بدونه يحسب بدون أبطال)")
    parser.add_argument("--list-heroes", action="store_true", help="عرض قائمة الأبطال المملوكين ومعرفاتهم في القلعة")
    parser.add_argument("--arena", action="store_true", help="حساب سعة الساحة (يستثني برج السديم)")
    parser.add_argument("--mass", action="store_true", help="حساب سعة مسيرة الحشد")
    parser.add_argument("--json", action="store_true", help="طباعة النتيجة بصيغة JSON كاملة")
    parser.add_argument("--save-memory", type=str, default="", help="حفظ لقطة الذاكرة الحية المستلمة في ملف JSON")
    parser.add_argument("positional_file", nargs="?", default="", help="مسار ملف JSON اختياري بدون --file")
    args = parser.parse_args()

    json_path = args.file or args.positional_file
    if args.email:
        code = asyncio.run(_run_live_castle(args))
        sys.exit(code)
    elif json_path:
        with open(json_path, "r", encoding="utf-8") as fh:
            memory_data = json.load(fh)
        if args.list_heroes:
            hmap = _get_hero_list_map(memory_data)
            print(f"\n[*] الأبطال المملوكون ({len(hmap)}):")
            for hid in sorted(hmap):
                hi = hmap[hid]
                print(f"  - ID={hid} | Lv={hi.get('level')} | Q={hi.get('quality')} | State={hi.get('state')}")
        hero_ids = [x.strip() for x in args.heroes.split(",") if x.strip()] if args.heroes else None
        result = calculate_march_capacity(memory_data, hero_ids=hero_ids, is_mass=args.mass, is_arena=args.arena)
        _print_result(result, label=os.path.basename(json_path), as_json=args.json)
    else:
        parser.print_help()
        sys.exit(1)


if __name__ == "__main__":
    main()